sp_widget.client_script:
api.controller = function($scope, $timeout, $rootScope) {

    var c = this;

    c.logs = [];
    c.currentIndex = 0;
    c.isRunning = false;
    c.success = false;
    c.finalMessage = '';

    var STORAGE_KEY = "am_setup_state";

    /* ✅ ACCORDION CONTROL */
    c.activeIndex = -1;

    c.toggleHelp = function(index) {

        if (c.activeIndex === index) {
            c.activeIndex = -1;
            c.logs[index].showHelp = false;
        } else {

            // close all
            c.logs.forEach(function(log) {
                log.showHelp = false;
            });

            c.activeIndex = index;
            c.logs[index].showHelp = true;
        }
    };

    function loadState() {
        var saved = sessionStorage.getItem(STORAGE_KEY);

        if (saved) {
            try {
                var data = JSON.parse(saved);

                c.logs = data.logs || [];
                c.success = data.success;
                c.finalMessage = data.message;

                c.currentIndex = c.logs.length;
                c.isRunning = false;
            } catch (e) {}
        }
    }

    function saveState() {
        sessionStorage.setItem(STORAGE_KEY, JSON.stringify({
            logs: c.logs,
            success: c.success,
            message: c.finalMessage
        }));
    }

    function startAnimation() {

        c.currentIndex = 0;

        function step() {
            if (c.currentIndex < c.logs.length) {
                c.currentIndex++;
                $timeout(step, 350);
            } else {
                c.isRunning = false;
                saveState();
            }
        }

        step();
    }

    c.$onInit = function() {
        loadState();
    };

    /* RUN SETUP */
    c.runSetup = function() {

        c.logs = [];
        c.currentIndex = 0;
        c.isRunning = true;

        sessionStorage.removeItem(STORAGE_KEY);

        c.server.get({
            action: 'runFixScript'
        }).then(function(res) {

            c.logs = res.data.result.logs || [];
            c.success = res.data.result.success;
            c.finalMessage = res.data.result.message;

            startAnimation();
            $rootScope.$broadcast('setup.completed');
        });
    };

    /* RESET */
    c.resetSetup = function() {

        sessionStorage.removeItem("am_setup_state");
        sessionStorage.removeItem("am_connection_state");
        sessionStorage.removeItem("am_failure_config");

        sessionStorage.setItem("am_force_reset", "true");
        sessionStorage.setItem("am_force_tenant_reset", "true");

        c.server.get({
            action: 'resetSetup'
        }).then(function() {

            $rootScope.$broadcast('setup.reset');
            window.location.reload();

        });
    };

};

sp_widget.css:
.hp-setup-widget {
  border: 2px solid #e5e7eb !important;
  border-radius: 10px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.05);
}
.hp-setup-widget .panel-heading {
  background: #f9fafb !important;
  border-bottom: 1px solid #e5e7eb;
  padding: 10px 14px;
  border-radius: 10px 10px 0 0;
}


.hp-setup-widget .header-flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
}


.hp-setup-widget .title {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
}


.hp-setup-widget .header-actions {
  display: flex;
  gap: 8px;
}


.hp-setup-widget .panel-body {
  padding: 14px;
}



.mapping-subtitle {
  color: #64748b;
  font-size: 13px;
  margin: 0 0 16px 0;
}



.section {
  margin-top: 10px;
  padding: 0;
}


.row-item {
  margin-bottom: 10px;
}


.row-line {
  display: flex;
  align-items: center;
  gap: 12px;
}


.icon { width: 25px; }
.name { width: 260px; }
.value { flex: 1; }



.pass { color: #22c55e; }
.fail { color: #ef4444; }



.result {
  margin-top: 14px;
  font-size: 14px;
  font-weight: 600;
  text-align: center;
}


.result.pass {
  background: #ecfdf5;
  border: 1px solid #bbf7d0;
  color: #166534;
  border-radius: 6px;
  padding: 10px;
}


.result.fail {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #991b1b;
  border-radius: 6px;
  padding: 10px;
}


.help-hint {
  font-size: 12px;
  color: #6b7280;
  margin-left: 8px;
}


.help-toggle {
  margin-left: auto;
  cursor: pointer;
  color: #2563eb;
}



.help-box {
  margin-left: 35px;
  margin-top: 8px;
  overflow: hidden;
  max-height: 0;
  opacity: 0;
  transition: max-height 0.3s ease, opacity 0.25s ease;
}


.help-box.open {
  max-height: 400px;
  opacity: 1;
  padding: 12px 14px;
  border-left: 4px solid #3b82f6;
  background: #eff6ff;
  border-radius: 6px;
}


.help-title {
  font-weight: 600;
  color: #1d4ed8;
  margin-bottom: 6px;
}


.help-content ul,
.help-content ol {
  padding-left: 18px;
  margin: 6px 0;
}

sp_widget.script:
(function() {

    var action = input && input.action;

    if (action === 'runFixScript') {

        var util = new x_hpws_wrkfrcexpam.WrkfrcExpAMCalibrationUtil();
        var result = util.runFixScript();

        data.result = result;
    }

    // ✅ RESET
    if (action === 'resetSetup') {

        var util2 = new x_hpws_wrkfrcexpam.WrkfrcExpAMCalibrationUtil();
        var res = util2.resetSetup();
        data.reset = res;
    }

})();
